create table if not exists public.replier_access ( profile_id uuid primary key references public.profiles (id) on delete cascade, granted_by uuid references public.profiles (id) on delete set null, granted_at timestamptz not null default now() ); alter table public.replier_access enable row level security; drop policy if exists "replier_access: ceo all" on public.replier_access; create policy "replier_access: ceo all" on public.replier_access for all using (public.is_ceo_role()) with check (public.is_ceo_role()); drop policy if exists "replier_access: read own" on public.replier_access; create policy "replier_access: read own" on public.replier_access for select using (profile_id = auth.uid()); create or replace function public.can_use_replier() returns boolean language sql stable security definer set search_path = public as $$ select public.is_ceo_role() or exists (select 1 from public.replier_access where profile_id = auth.uid()); $$; revoke all on function public.can_use_replier() from public; grant execute on function public.can_use_replier() to authenticated; create or replace function public.set_replier_access(target uuid, allow boolean) returns void language plpgsql security definer set search_path = public as $$ begin if not public.is_ceo_role() then raise exception 'Only the CEO can choose who uses the Professional Replier.'; end if; if not exists (select 1 from public.profiles where id = target and role in ('operations_manager', 'staff', 'videographer')) then raise exception 'That person is not on the team.'; end if; if allow then insert into public.replier_access (profile_id, granted_by) values (target, auth.uid()) on conflict (profile_id) do nothing; else delete from public.replier_access where profile_id = target; end if; end; $$; revoke all on function public.set_replier_access(uuid, boolean) from public; grant execute on function public.set_replier_access(uuid, boolean) to authenticated; create table if not exists public.replier_playbook ( id boolean primary key default true check (id), needs_ceo text not null default '' check (char_length(needs_ceo) <= 6000), house_style text not null default '' check (char_length(house_style) <= 6000), never_promise text not null default '' check (char_length(never_promise) <= 6000), facts text not null default '' check (char_length(facts) <= 12000), updated_by uuid references public.profiles (id) on delete set null, updated_at timestamptz not null default now() ); insert into public.replier_playbook (id, needs_ceo, house_style, never_promise, facts) values ( true, 'Wanting to go ahead with another month, renew, or sign up
Anything about the contract or its terms
Prices, discounts, deals or payment plans
Refunds, credits, chargebacks or late payment
Complaints, or a client who sounds unhappy or wants to leave
Cancelling, pausing or changing the package
Adding work that is not in their package (extra videos, ads, shoots)
Anything legal, or about using someone''s likeness, music or brand
Anything you are unsure about', 'British English. Warm, confident and short, like a good account manager on WhatsApp.
Use their first name when we know it.
Answer the question in the first line.
One clear next step at the end.
No jargon, no long paragraphs, no more than one emoji.
Never sound like a robot or a template.', 'A filming, editing or posting date we have not confirmed
Results, views or follower numbers
Anything free, discounted or extra
That the CEO will do something
Changes to the contract', 'Advatar makes short-form video content for businesses and personal brands: planning, filming, editing and posting.
Videos are finished the week before they go out.
Clients review and approve videos before they are posted.' ) on conflict (id) do nothing; alter table public.replier_playbook enable row level security; drop policy if exists "replier_playbook: users read" on public.replier_playbook; create policy "replier_playbook: users read" on public.replier_playbook for select using (public.can_use_replier()); drop policy if exists "replier_playbook: ceo writes" on public.replier_playbook; create policy "replier_playbook: ceo writes" on public.replier_playbook for all using (public.is_ceo_role()) with check (public.is_ceo_role()); create table if not exists public.replier_examples ( id uuid primary key default gen_random_uuid(), client_message text not null check (char_length(client_message) between 1 and 4000), reply text not null check (char_length(reply) between 1 and 4000), note text check (note is null or char_length(note) <= 1000), created_by uuid references public.profiles (id) on delete set null, created_at timestamptz not null default now() ); alter table public.replier_examples enable row level security; drop policy if exists "replier_examples: users read" on public.replier_examples; create policy "replier_examples: users read" on public.replier_examples for select using (public.can_use_replier()); drop policy if exists "replier_examples: ceo writes" on public.replier_examples; create policy "replier_examples: ceo writes" on public.replier_examples for all using (public.is_ceo_role()) with check (public.is_ceo_role()); create table if not exists public.replier_runs ( id uuid primary key default gen_random_uuid(), created_by uuid not null default auth.uid() references public.profiles (id) on delete cascade, client_id uuid references public.clients (id) on delete set null, replying_as text not null check (replying_as in ('sales', 'videographer', 'operations', 'ceo')), channel text not null check (channel in ('whatsapp', 'instagram', 'email', 'text')), client_message text not null check (char_length(client_message) between 1 and 8000), extra text check (extra is null or char_length(extra) <= 2000), result jsonb not null, needs_ceo boolean not null default false, ceo_reason text, model text, cost_usd numeric(12, 6), chosen int check (chosen is null or chosen between 0 and 2), copied_at timestamptz, rating smallint check (rating is null or rating in (-1, 1)), feedback text check (feedback is null or char_length(feedback) <= 2000), escalated_at timestamptz, created_at timestamptz not null default now() ); alter table public.replier_runs add column if not exists escalated_at timestamptz; create index if not exists replier_runs_by_person on public.replier_runs (created_by, created_at desc); create index if not exists replier_runs_needs_ceo on public.replier_runs (needs_ceo, created_at desc) where needs_ceo; alter table public.replier_runs enable row level security; drop policy if exists "replier_runs: read own or ceo" on public.replier_runs; create policy "replier_runs: read own or ceo" on public.replier_runs for select using (public.is_ceo_role() or (created_by = auth.uid() and public.can_use_replier())); drop policy if exists "replier_runs: add own" on public.replier_runs; create policy "replier_runs: add own" on public.replier_runs for insert with check (created_by = auth.uid() and public.can_use_replier()); drop policy if exists "replier_runs: update own or ceo" on public.replier_runs; create policy "replier_runs: update own or ceo" on public.replier_runs for update using (public.is_ceo_role() or (created_by = auth.uid() and public.can_use_replier())) with check (public.is_ceo_role() or (created_by = auth.uid() and public.can_use_replier())); drop policy if exists "replier_runs: delete own or ceo" on public.replier_runs; create policy "replier_runs: delete own or ceo" on public.replier_runs for delete using (public.is_ceo_role() or created_by = auth.uid()); create or replace function public.replier_runs_guard() returns trigger language plpgsql as $$ begin new.created_by := old.created_by; new.client_id := old.client_id; new.replying_as := old.replying_as; new.channel := old.channel; new.client_message := old.client_message; new.extra := old.extra; new.result := old.result; new.needs_ceo := old.needs_ceo; new.ceo_reason := old.ceo_reason; new.model := old.model; new.cost_usd := old.cost_usd; new.created_at := old.created_at; if current_user not in ('postgres', 'supabase_admin') then new.escalated_at := old.escalated_at; end if; return new; end; $$; drop trigger if exists replier_runs_guard on public.replier_runs; create trigger replier_runs_guard before update on public.replier_runs for each row execute function public.replier_runs_guard(); create or replace function public.replier_escalate(target uuid) returns void language plpgsql security definer set search_path = public as $$ declare r public.replier_runs; who text; client_name text; ceo record; begin select * into r from public.replier_runs where id = target; if r.id is null or not r.needs_ceo or r.escalated_at is not null then return; end if; if r.created_by <> auth.uid() and not public.is_ceo_role() then raise exception 'Not your reply.'; end if; select coalesce(nullif(btrim(full_name), ''), 'Someone on the team') into who from public.profiles where id = r.created_by; select name into client_name from public.clients where id = r.client_id; for ceo in select id from public.profiles where role = 'ceo' loop if ceo.id = r.created_by then continue; end if; insert into public.tasks (client_id, assigned_to, text, due_date, priority) values ( r.client_id, ceo.id, left(concat('Decide on ', coalesce(client_name, 'a client'), '''s message (', who, '): ', coalesce(r.ceo_reason, 'needs you')), 500), current_date, 'high' ); end loop; update public.replier_runs set escalated_at = now() where id = r.id; end; $$; revoke all on function public.replier_escalate(uuid) from public; grant execute on function public.replier_escalate(uuid) to authenticated;
